// ---------------------------------------------------------------------------
// chrome.generated.ts — generated by nvoos-astro-forge (Proposal 120 §2);
// edits are overwritten on re-scaffold. The source site chrome: topbar lines,
// logo, tagline, nav, call button, footer blocks, copyright — facts only, the
// layout rebuilds them with its own components. Deterministic: same profile,
// same bytes.
// ---------------------------------------------------------------------------

export interface ForgeChrome {
	topbar?: string[];
	logo?: { src?: string; alt?: string };
	tagline?: string;
	nav?: Array<{ label: string; href: string }>;
	call?: { label: string; href: string; bg?: string; ink?: string };
	footerBlocks?: Array<{ title?: string; items: string[] }>;
	copyright?: string;
	/** The site favicon (the first <link rel="icon"> href, absolute). */
	favicon?: string;
	/** The source icon-font stylesheet (the icons CSS link, e.g. the theme's
	 * auxin-icon.css) — the rebuild's icon markers carry the source glyph
	 * classes and this sheet draws them (the customer's own asset). */
	iconCss?: string;
	/** The subfooter text color (the source paints white-ish text on its
	 * dark footer). */
	footerInk?: string;
	/** The footer brand logo (the footer-widget media image). */
	footerLogo?: { src?: string; alt?: string };
	/** The footer background color (resolved from the footer-widget CSS). */
	footerBg?: string;
}

export const chrome: ForgeChrome | undefined = undefined;
